#!/usr/bin/env python3
"""Fail when Windows 7 silently diverges from shared root sources.

The comparison is intentionally narrow only in *where configuration differs*:
all files below lib/, test/, assets/, and windows/ must exist on both sides.
Content differences are accepted only for the exact paths listed in ALLOWED.
"""

from __future__ import annotations

import argparse
import os
import shutil
import sys
import tempfile
from pathlib import Path

COMPARED_DIRS = ("lib", "test", "assets", "windows")

# Exact generated files may still match before Flutter 3.16.9 regenerates them.
ALLOW_MAY_MATCH = {"windows/flutter/generated_plugin_registrant.h"}

ALLOWED = {
    "lib/app/jadwal_windows_app.dart": "Windows 7 window/bootstrap behavior",
    "lib/features/management/presentation/pages/settings_page.dart": (
        "Windows 7 saves backups locally; modern/mobile keeps system share"
    ),
    "lib/features/management/presentation/pages/subject_constraints_page.dart": (
        "DropdownButtonFormField uses value on Flutter 3.16.9"
    ),
    "lib/features/timetable/presentation/pages/timetable_page.dart": (
        "Windows 7 saves exports locally; modern/mobile keeps system share"
    ),
    "lib/main_windows.dart": "Windows 7 entry point and platform identity",
    "windows/CMakeLists.txt": "Windows 7 executable name",
    "windows/flutter/generated_plugin_registrant.cc": "Generated by Flutter 3.16.9 for the Windows 7 plugin set",
    "windows/flutter/generated_plugin_registrant.h": "Generated header differs under Flutter 3.16.9",
    "windows/flutter/generated_plugins.cmake": "Generated by Flutter 3.16.9 for the Windows 7 plugin set",
    "windows/packaging/README.md": "Windows 7 artifact documentation",
    "windows/packaging/jadwal_v2.iss": "Windows 7 installer identity and executable",
    "windows/runner/Runner.rc": "Windows 7 executable metadata and icon identity",
    "windows/runner/runner.exe.manifest": "Windows 7 supported-OS declarations",
}


def files_below(base: Path) -> set[str]:
    result: set[str] = set()
    for directory in COMPARED_DIRS:
        root = base / directory
        if not root.is_dir():
            raise ValueError(f"missing compared directory: {root}")
        result.update(str(path.relative_to(base)).replace("\\", "/") for path in root.rglob("*") if path.is_file())
    return result


def compare(root: Path, windows7: Path, *, verbose: bool = True) -> list[str]:
    root_files = files_below(root)
    w7_files = files_below(windows7)
    errors: list[str] = []

    for path in sorted(root_files - w7_files):
        errors.append(f"MISSING_IN_WINDOWS7 {path}")
    for path in sorted(w7_files - root_files):
        errors.append(f"WINDOWS7_ONLY {path}")

    allowed_seen: set[str] = set()
    for path in sorted(root_files & w7_files):
        if (root / path).read_bytes() == (windows7 / path).read_bytes():
            continue
        reason = ALLOWED.get(path)
        if reason is None:
            errors.append(f"UNALLOWED_CONTENT_DIFF {path}")
        else:
            allowed_seen.add(path)
            if verbose:
                print(f"ALLOWED_CONTENT_DIFF {path}: {reason}")

    # An allowlist entry that no longer differs is stale and must be reviewed.
    for path in sorted(set(ALLOWED) - allowed_seen - ALLOW_MAY_MATCH):
        errors.append(f"STALE_ALLOWLIST_ENTRY {path}: {ALLOWED[path]}")

    return errors


def self_test(root: Path, windows7: Path) -> None:
    positive = compare(root, windows7, verbose=False)
    if positive:
        raise RuntimeError("positive guard test failed:\n" + "\n".join(positive))
    print("SELF_TEST positive: PASS")

    with tempfile.TemporaryDirectory(prefix="windows7-drift-negative-") as tmp:
        sandbox = Path(tmp) / "windows_7"
        shutil.copytree(windows7, sandbox)
        probe = sandbox / "lib/core/constants/app_constants.dart"
        if not probe.is_file() or str(probe.relative_to(sandbox)).replace("\\", "/") in ALLOWED:
            raise RuntimeError("negative-test probe is absent or allowlisted")
        probe.write_bytes(probe.read_bytes() + b"\n// deliberate negative drift probe\n")
        negative = compare(root, sandbox, verbose=False)
        expected = "UNALLOWED_CONTENT_DIFF lib/core/constants/app_constants.dart"
        if expected not in negative:
            raise RuntimeError("negative guard test failed to detect probe:\n" + "\n".join(negative))
        print(f"SELF_TEST negative: PASS ({expected})")


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--root", type=Path, default=Path("."))
    parser.add_argument("--windows7", type=Path, default=Path("apps/windows_7"))
    parser.add_argument("--self-test", action="store_true")
    args = parser.parse_args()

    root = args.root.resolve()
    windows7 = args.windows7.resolve()
    try:
        if args.self_test:
            self_test(root, windows7)
            return 0
        errors = compare(root, windows7)
    except (OSError, ValueError, RuntimeError) as error:
        print(f"DRIFT_GUARD_ERROR {error}", file=sys.stderr)
        return 2

    if errors:
        print("\n".join(errors), file=sys.stderr)
        if os.environ.get("GITHUB_ACTIONS") == "true":
            for error in errors:
                # Keep the message annotation-readable; paths are included in each error.
                print(f"::error title=Windows 7 drift guard::{error}")
        print(f"DRIFT_GUARD_FAIL errors={len(errors)}", file=sys.stderr)
        return 1
    print(f"DRIFT_GUARD_PASS allowed_differences={len(ALLOWED)}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
